#!/usr/bin/env python3
"""Translate independent JSON oracle data to Rust test constants; no mechanics."""
import argparse
import json
from pathlib import Path


def literal(value):
    if isinstance(value, list):
        return '[' + ', '.join(literal(x) for x in value) + ']'
    return repr(float(value))


def render(root):
    cases = json.loads((root / 'element_cases.json').read_text())
    expected = json.loads((root / 'expected.json').read_text())
    lines = ['// Generated by generators/emit_rust.py from the independent JSON oracle.',
             '// Do not edit; no product implementation is read by either generator.',
             'use super::{OracleCase, SweepCase};',
             'pub(super) const CASES: &[OracleCase] = &[']
    for c, e in zip(cases['stiffness_cases'], expected['stiffness_cases'], strict=True):
        assert c['id'] == e['id']
        fields = {'name': json.dumps(c['id']), 'xi': literal(c['x_i']),
                  'xj': literal(c['x_j']), 'reference': literal(c['y_reference']),
                  'radius': literal(c['radius']), 'kin': literal(c['k_in']),
                  'kout': literal(c['k_out']), 'load': literal(e['w_global'])}
        for field, key in [('f_eb', 'end_flexibility_local_euler_bernoulli'),
                           ('f_v2', 'end_flexibility_local_v2'),
                           ('k_v2', 'global_stiffness_v2'),
                           ('p_v2', 'consistent_uniform_load_global_v2'),
                           ('d_v2', 'free_tip_deflection_local_v2')]:
            fields[field] = literal(e[key])
        lines.append('    OracleCase { ' + ', '.join(f'{k}: {v}' for k, v in fields.items()) + ' },')
    lines.extend(['];', 'pub(super) const SWEEPS: &[SweepCase] = &['])
    for e in expected['sweep_cases']:
        c = e['inputs']
        fields = {'name': json.dumps(e['id']), 'xi': literal(c['x_i']),
                  'xj': literal(c['x_j']), 'reference': literal(c['y_reference']),
                  'radius': literal(c['radius']),
                  'f': literal(e['shear_flexibility_over_R_per_GAs']),
                  'd': literal(e['shear_udl_translation_over_R2_per_GAs'])}
        lines.append('    SweepCase { ' + ', '.join(f'{k}: {v}' for k, v in fields.items()) + ' },')
    return '\n'.join(lines + ['];', ''])


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    root = Path(__file__).resolve().parents[1]
    output = root / 'kernel_cases.rs'
    data = render(root)
    if args.check:
        if output.read_text() != data:
            raise SystemExit('kernel_cases.rs differs; run emit_rust.py')
    else:
        output.write_text(data)


if __name__ == '__main__':
    main()
